# Test for the GET /pet/{petId} endpoint
@pytest.mark.parametrize(
    "pet_id, expected_status_code, description",
    [
        (10, 200, "Pet found with valid ID."),
        (0, 400, "Invalid ID supplied."),
        (99999, 404, "Pet not found."),
    ],
)
def test_get_pet_by_id(base_url, auth_headers, pet_id, expected_status_code, description):
    """
    Test GET request for fetching a pet by ID.
    Covers success case, invalid ID, and not found scenarios.
    """
    url = f"{base_url}/pet/{pet_id}"
    headers = auth_headers

    response = requests.get(url, headers=headers)

    assert response.status_code == expected_status_code, f"Failed: {description}"

    if expected_status_code == 200:
        response_json = response.json()
        validate_response_schema(response_json, valid_response_schema)

    elif expected_status_code == 400:
        assert response.json().get("message", "").startswith("Invalid"), "Expected invalid ID error."

    elif expected_status_code == 404:
        assert response.json().get("message", "").startswith("Pet not found"), "Expected pet not found error."


